"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["48078"],{72125(e){e.exports=JSON.parse('{"id":"FIN-1080","slug":"return-on-sales","term":"Return on Sales (ROS)","also_known_as":["ROS"],"difficulty":"Advanced","definition":"Return on sales (ROS) is a company\'s operating profit divided by its revenue, showing how much operating profit it makes from each unit of sales.","explanation":["Return on sales measures operating efficiency. It shows what share of revenue remains after paying the costs of running the business, before interest and taxes.","For example, a company with revenue of 1,500,000 and operating profit of 150,000 has a return on sales of 10%. For every 100 of sales, it keeps 10 as operating profit.","ROS is very similar to operating margin, and the two terms are often used interchangeably. Some analysts calculate ROS using net income instead, which makes it the same as net profit margin, so it is worth checking which definition is being used.","Comparing ROS over time shows whether a company is controlling costs and maintaining pricing power. Comparisons between companies are most meaningful within the same industry, since some businesses, such as supermarkets, naturally operate on thin margins, while others, such as software firms, can achieve much higher ones."],"note":"","total":1725,"prev":{"slug":"return-on-investment","term":"Return on Investment (ROI)"},"next":{"slug":"revaluation","term":"Revaluation"}}')}}]);